/* Named so the catalogue records the decision rather than silently omitting them. */
const REFUSED = {
  '09-utility': [
    { ...c('terminal', 'Terminal', 'A shell emulator.', ['at-rest'], 'n/a', 'n/a', 'n/a', 'n/a', 'n/a', ['primereact:terminal']),
      status: 'not-applicable',
      why: 'A shell emulator is an application, not a design-system component.' },
    { ...c('border-beam', 'Border beam', 'A travelling highlight around a border.', ['at-rest'], 'n/a', 'n/a', 'n/a', 'n/a', 'n/a', ['antd:border-beam']),
      status: 'not-applicable',
      why: 'Crystal specifies edge treatment as the Resin optical rim. A second, unrelated mechanism for a moving border would contradict the material spec, and the ambient tier that would have owned it is deferred.' },
  ],
};

const CHARTS_META = {
  id: 'charts',
  name: 'Charts',
  description: 'Data visualisation on one shared surface. Crystal named no charting component before 2.0 while every React benchmark shipped one; these are specified against MUI X Charts, PrimeReact Chart and Mantine Charts. Every chart owes a text equivalent of its data — a chart is a second representation, never the only one.',
  components: [],
};

let added = 0;
const report = [];

for (const [file, entries] of Object.entries({ ...ADDITIONS })) {
  const full = path.join(DIR, `${file}.json`);
  let doc;
  if (fs.existsSync(full)) {
    doc = JSON.parse(fs.readFileSync(full, 'utf8'));
  } else if (file === '10-charts') {
    doc = { ...CHARTS_META };
  } else {
    console.error(`No catalogue file ${file}.json and no template for it.`);
    process.exit(1);
  }
  const have = new Set(doc.components.map((x) => x.id));
  const fresh = entries.filter((x) => !have.has(x.id));
  const refused = (REFUSED[file] || []).filter((x) => !have.has(x.id));
  if (!fresh.length && !refused.length) continue;
  doc.components.push(...fresh, ...refused);
  added += fresh.length + refused.length;
  report.push(`${file}: +${fresh.length}${refused.length ? ` (+${refused.length} not-applicable)` : ''} -> ${doc.components.length}`);
  if (WRITE) fs.writeFileSync(full, JSON.stringify(doc, null, 2) + '\n');
}

if (!added) { console.log('The catalogue already carries every addition.'); process.exit(0); }
console.log(`${added} components to add:`);
for (const line of report) console.log('  ' + line);
console.log(WRITE ? '\nWritten. Run tools/build-catalogue.cjs to regenerate parity.json.' : '\nRe-run with --write to apply.');
